create extension if not exists "pgcrypto";
create table public.organizations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, plan text not null default 'trial' check (plan in ('trial','starter','pro','enterprise')), trial_ends_at timestamptz not null default (now() + interval '7 days'), created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, title text not null, prompt text, width integer not null, height integer not null, duration_seconds integer not null default 15, status text not null default 'draft' check (status in ('draft','queued','rendering','ready','failed')), output_url text, created_at timestamptz not null default now());
create table public.screens (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, location text, width integer not null, height integer not null, device_token_hash text unique, last_seen_at timestamptz, created_at timestamptz not null default now());
create table public.deployments (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, screen_id uuid not null references public.screens(id) on delete cascade, status text not null default 'queued' check (status in ('queued','downloading','live','failed')), scheduled_at timestamptz, created_at timestamptz not null default now());
alter table public.organizations enable row level security; alter table public.projects enable row level security; alter table public.screens enable row level security; alter table public.deployments enable row level security;
create policy "owners manage organizations" on public.organizations for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy "owners manage projects" on public.projects for all to authenticated using (exists (select 1 from public.organizations o where o.id = organization_id and o.owner_id = (select auth.uid()))) with check (exists (select 1 from public.organizations o where o.id = organization_id and o.owner_id = (select auth.uid())));
create policy "owners manage screens" on public.screens for all to authenticated using (exists (select 1 from public.organizations o where o.id = organization_id and o.owner_id = (select auth.uid()))) with check (exists (select 1 from public.organizations o where o.id = organization_id and o.owner_id = (select auth.uid())));
create policy "owners manage deployments" on public.deployments for all to authenticated using (exists (select 1 from public.projects p join public.organizations o on o.id = p.organization_id where p.id = project_id and o.owner_id = (select auth.uid()))) with check (exists (select 1 from public.projects p join public.organizations o on o.id = p.organization_id where p.id = project_id and o.owner_id = (select auth.uid())));
grant usage on schema public to authenticated; grant select, insert, update, delete on public.organizations, public.projects, public.screens, public.deployments to authenticated;
